import java.io.*;
import java.util.*;

public class Main {
    static long[][] Comb = new long[62][62];
    static long[][] A = new long[32][32];
    static long[][] B = new long[32][32];
    static long[][] CC = new long[32][32];
    static ArrayList<Pair>[][] P = new ArrayList[32][2];
    static ArrayList<Pair>[][] Q = new ArrayList[32][2];
    static int R, C, n;
    static char[] p;
    static long TT, MM, Res;

    static class Pair {
        long first, second;
        Pair(long f, long s) { first = f; second = s; }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        p = br.readLine().toCharArray();
        n = R + C;

        // Initialize arrays
        for (int i = 0; i <= 60; i++) {
            Comb[i][0] = 1;
            for (int j = 1; j <= i; j++)
                Comb[i][j] = Comb[i-1][j-1] + Comb[i-1][j];
        }

        TT = Comb[2*n][2*R];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i > 0) {
                    A[i][j] = Comb[i-1][R-1] * (Comb[2*n - i][R] - Comb[j][R]);
                }
                if (j > 0) {
                    B[i][j] = Comb[j-1][R-1] * (Comb[2*n - j][R] - Comb[i][R]);
                }
            }
        }

        CC[0][0] = 1;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i != n && p[i+j] != 'B') CC[i+1][j] += CC[i][j];
                if (j != n && p[i+j] != 'A') CC[i][j+1] += CC[i][j];
            }
        }

        // Initialize P and Q
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                P[i][j] = new ArrayList<>();
                Q[i][j] = new ArrayList<>();
            }
        }

        // Put function
        for (int i = R; i <= n; i++) {
            if (p[i+R-1] != 'B') {
                Put(R, i, A[R][i], Comb[i+R-1][R-1], CC[R-1][i], 0);
            }
            if (p[i+R-1] != 'A') {
                Put(i, R, B[i][R], Comb[i+R-1][R-1], CC[i][R-1], 1);
            }
        }

        // Make function
        for (int i = R; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                Make(P[i][j]);
                Make(Q[i][j]);
            }
        }

        MM = TT + 1;
        Res = 0;

        Calc1(n, n, 0, 0);
        Calc1(n, n, 0, 1);
        Calc2(n, n, 0, 0);
        Calc2(n, n, 0, 1);

        System.out.println(Res);
    }

    static void Put(int x, int y, long g, long c1, long c2, int ck) {
        if (x + y == R + n) {
            P[x][ck].add(new Pair(g, c1));
            if (c2 != 0) Q[x][ck].add(new Pair(g, c2));
            return;
        }
        Put(x+1, y, g + (ck == 0 ? A[x+1][y] : 0), c1, (p[x+y] != 'B' ? c2 : 0), ck);
        Put(x, y+1, g + (ck == 1 ? B[x][y+1] : 0), c1, (p[x+y] != 'A' ? c2 : 0), ck);
    }

    static void Make(ArrayList<Pair> list) {
        if (list.isEmpty()) return;
        Collections.sort(list, (a, b) -> Long.compare(a.first, b.first));
        int cnt = 0;
        long sum = 0;
        for (int i = 0; i < list.size(); i++) {
            sum += list.get(i).second;
            if (i == list.size()-1 || list.get(i).first != list.get(i+1).first) {
                list.set(cnt++, new Pair(list.get(i).first, sum));
                sum = 0;
            }
        }
        while (list.size() > cnt) list.remove(list.size()-1);
    }

    static void Calc1(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            ArrayList<Pair> cur = P[x][ck];
            if (cur.isEmpty()) return;
            long target = (TT + 1) / 2 - g;
            int t = lowerBound(cur, target);
            if (t < cur.size() && cur.get(t).second > 0) {
                long tp = (cur.get(t).first + g) * 2 - TT;
                if (tp < 0) tp = -tp;
                if (MM > tp) MM = tp;
            }
            if (t > 0 && cur.get(t-1).second > 0) {
                long tp = (cur.get(t-1).first + g) * 2 - TT;
                if (tp < 0) tp = -tp;
                if (MM > tp) MM = tp;
            }
            return;
        }
        Calc1(x-1, y, g + (ck == 0 ? A[x][y] : 0), ck);
        Calc1(x, y-1, g + (ck == 1 ? B[x][y] : 0), ck);
    }

    static void Calc2(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            ArrayList<Pair> cur = Q[x][ck];
            long target = (TT + 1) / 2 - g;
            int t = lowerBound(cur, target);
            if (t < cur.size() && cur.get(t).second > 0) {
                long tp = (cur.get(t).first + g) * 2 - TT;
                if (tp < 0) tp = -tp;
                if (MM == tp) Res += cur.get(t).second;
            }
            if (t > 0 && cur.get(t-1).second > 0) {
                long tp = (cur.get(t-1).first + g) * 2 - TT;
                if (tp < 0) tp = -tp;
                if (MM == tp) Res += cur.get(t-1).second;
            }
            return;
        }
        if (p[x+y-1] != 'B') Calc2(x-1, y, g + (ck == 0 ? A[x][y] : 0), ck);
        if (p[x+y-1] != 'A') Calc2(x, y-1, g + (ck == 1 ? B[x][y] : 0), ck);
    }

    static int lowerBound(ArrayList<Pair> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid).first < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}
